<script setup>
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '../../app/stores/auth.store'
import { tasksService, workflowActions } from './tasks.service'
import { commentsService } from './comments.service'
import { attachmentsService } from './attachments.service'
import { projectsService } from '../projects/projects.service'
import { taskPayload, runAdminMutation } from '../../app/services/admin-ui'
import AsyncState from '../../shared/components/AsyncState.vue'
import Badges from '../../shared/components/Badges.vue'
import BaseModal from '../../shared/components/BaseModal.vue'
import TaskForm from './TaskForm.vue'
import MemberSelector from '../projects/MemberSelector.vue'
const props = defineProps({ taskId: String }); const auth = useAuthStore(); const task = ref(null); const subtasks = ref([]); const blockers = ref([]); const dependencies = ref([]); const dependents = ref([]); const activity = ref([]); const comments = ref([]); const attachments = ref([]); const members = ref([]); const stages = ref([]); const loading = ref(true); const error = ref(''); const busy = ref(false); const subtaskTitle = ref(''); const blockerType = ref('TechnicalIssue'); const blockerDescription = ref(''); const commentContent = ref(''); const editingComment = ref(null); const selectedFile = ref(null); const editModal = ref(false); const moveStageId = ref('')
const mutable = computed(() => ['Pending', 'InProgress', 'Blocked'].includes(task.value?.status)); const activeBlockers = computed(() => blockers.value.filter(x => !x.isResolved)); const canManage = computed(() => auth.isAdmin); const availableAssigneeMembers = computed(() => members.value.map(member => ({ ...member, id: member.userId, isActive: true }))); const activeStages = computed(() => stages.value.filter(stage => stage.isActive && stage.id !== task.value?.stageId)); const actions = computed(() => workflowActions(task.value?.status, canManage.value)); const canDeleteComment = comment => comment.author.id === auth.user?.id || canManage.value; const canDeleteAttachment = attachment => attachment.uploadedBy.id === auth.user?.id || canManage.value
async function load() { loading.value = true; error.value = ''; try { const data = await Promise.all([tasksService.get(props.taskId), tasksService.subtasks(props.taskId), tasksService.blockers(props.taskId), tasksService.dependencies(props.taskId), tasksService.dependents(props.taskId), tasksService.activity(props.taskId), commentsService.list(props.taskId), attachmentsService.list(props.taskId)]); [task.value, subtasks.value, blockers.value, dependencies.value, dependents.value] = data; activity.value = data[5].items || []; comments.value = data[6].items || []; attachments.value = data[7] || []; if (canManage.value) [members.value, stages.value] = await Promise.all([projectsService.members(task.value.projectId), projectsService.stages(task.value.projectId)]) } catch (e) { error.value = e.message } finally { loading.value = false } }
async function run(operation) { busy.value = true; await runAdminMutation(operation, load, value => error.value = value); busy.value = false }
async function comment() { if (commentContent.value.trim()) await run(async () => { await commentsService.create(task.value.id, commentContent.value); commentContent.value = '' }) }
async function updateComment(comment) { await run(async () => { await commentsService.update(task.value.id, comment.id, editingComment.value.content); editingComment.value = null }) }
function selectFile(event) { selectedFile.value = event.target.files?.[0] || null }
async function upload() { if (selectedFile.value) await run(async () => { await attachmentsService.upload(task.value.id, selectedFile.value); selectedFile.value = null }) }
async function download(attachment) { try { const blob = await attachmentsService.download(`/api/tasks/${task.value.id}/attachments/${attachment.id}/download`); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = attachment.fileName; link.click(); URL.revokeObjectURL(url) } catch (e) { error.value = e.message } }
const formatFileSize = bytes => bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} KB` : `${(bytes / (1024 * 1024)).toFixed(1)} MB`
function activityText(item) { return ({ TaskStarted: 'inició la tarea', TaskSubmittedForReview: 'envió la tarea a revisión', TaskChangesRequested: 'solicitó cambios', TaskCompleted: 'completó la tarea', BlockerReported: 'reportó un bloqueo', BlockerResolved: 'resolvió un bloqueo', SubtaskCompleted: 'completó una subtarea', SubtaskCreated: 'añadió una subtarea', DependencyAdded: 'añadió una dependencia', CommentAdded: 'comentó en la tarea', CommentEdited: 'editó un comentario', CommentDeleted: 'eliminó un comentario', AttachmentAdded: `adjuntó ${item.metadata?.fileName || 'un archivo'}`, AttachmentDeleted: `eliminó ${item.metadata?.fileName || 'un archivo'}` }[item.activityType] || item.activityType) }
onMounted(load)
</script>
<template><section class="page task-page"><AsyncState :loading="loading" :error="error" :empty="false"><header class="page-header task-header"><div><RouterLink :to="`/projects/${task.projectId}`" class="back-link">← Volver al tablero</RouterLink><h1>{{ task.title }}</h1><div class="inline-badges"><Badges :value="task.status" /><Badges :value="task.priority" type="priority" /></div></div><div class="action-row"><button v-if="canManage" class="button secondary" :disabled="busy" @click="editModal = true">Editar</button><button v-for="action in actions" :key="action.id" :class="['button', action.secondary ? 'secondary' : 'primary']" :disabled="busy" @click="run(() => tasksService.workflow(task.id, action.id, task.version))">{{ action.label }}</button></div></header><p v-if="task.description" class="description">{{ task.description }}</p><p v-else class="muted">Esta tarea no tiene descripción.</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="detail-grid"><section class="detail-section" v-if="canManage"><header><h2>Administración</h2></header><label class="move-select">Mover a etapa<select v-model="moveStageId"><option value="">Selecciona una etapa</option><option v-for="stage in activeStages" :key="stage.id" :value="stage.id">{{ stage.name }}</option></select></label><button class="button secondary" :disabled="busy || !moveStageId" @click="run(() => tasksService.move(task.id, moveStageId, task.version))">Mover tarea</button><h3>Responsables</h3><div class="assignee-chips"><span v-for="person in task.assignees" :key="person.id" class="assignee-chip">{{ person.fullName }}<button :disabled="busy" @click="run(() => tasksService.removeAssignee(task.id, person.id, task.version))">×</button></span></div><MemberSelector :users="availableAssigneeMembers" :members="task.assignees.map(item => ({ ...item, userId: item.id }))" :submitting="busy" @add="userId => run(() => tasksService.addAssignee(task.id, userId, task.version))" /></section><section class="detail-section"><header><h2>Subtareas <small>{{ task.subtaskProgress.completed }}/{{ task.subtaskProgress.total }}</small></h2></header><form v-if="mutable" class="compact-form" @submit.prevent="run(async () => { await tasksService.createSubtask(task.id, subtaskTitle, task.version); subtaskTitle = '' })"><input v-model="subtaskTitle" placeholder="Añadir subtarea" required /><button class="button secondary" :disabled="busy">Añadir</button></form><ul class="check-list"><li v-for="item in subtasks" :key="item.id"><button v-if="mutable" class="check-button" @click="run(() => tasksService.subtaskAction(task.id, item.id, item.isCompleted ? 'reopen' : 'complete', task.version))">{{ item.isCompleted ? '✓' : '' }}</button><span :class="{ done: item.isCompleted }">{{ item.title }}</span><button v-if="mutable" class="icon-button danger" @click="run(() => tasksService.deleteSubtask(task.id, item.id, task.version))">×</button></li><li v-if="!subtasks.length" class="muted">No hay subtareas.</li></ul></section><section class="detail-section"><header><h2>Bloqueos</h2></header><div v-if="activeBlockers.length" class="blocker-list"><article v-for="blocker in activeBlockers" :key="blocker.id"><b>{{ blocker.type }}</b><p>{{ blocker.description }}</p><button v-if="mutable" class="text-button" @click="run(() => tasksService.resolveBlocker(task.id, blocker.id, task.version))">Resolver</button></article></div><p v-else class="muted">No hay bloqueos activos.</p><form v-if="mutable" class="blocker-form" @submit.prevent="run(async () => { await tasksService.reportBlocker(task.id, blockerType, blockerDescription, task.version); blockerDescription = '' })"><select v-model="blockerType"><option>Dependency</option><option>Information</option><option>Approval</option><option>TechnicalIssue</option><option>External</option><option>Other</option></select><textarea v-model="blockerDescription" placeholder="Describe el bloqueo" required /><button class="button secondary" :disabled="busy">Reportar bloqueo</button></form></section><section class="detail-section"><header><h2>Dependencias</h2></header><ul class="link-list"><li v-for="item in dependencies" :key="item.id"><RouterLink :to="`/tasks/${item.dependsOnTask.id}`">{{ item.dependsOnTask.title }}</RouterLink><Badges :value="item.dependsOnTask.status" /></li><li v-if="!dependencies.length" class="muted">No depende de otras tareas.</li></ul></section><section class="detail-section attachments"><header><h2>Archivos</h2></header><label class="file-picker">Adjuntar archivo<input type="file" @change="selectFile" /></label><button class="button secondary" :disabled="busy || !selectedFile" @click="upload">{{ busy ? 'Subiendo...' : 'Subir archivo' }}</button><p v-if="selectedFile" class="muted">{{ selectedFile.name }}</p><ul class="attachment-list"><li v-for="attachment in attachments" :key="attachment.id"><div><b>{{ attachment.fileName }}</b><small>{{ attachment.contentType }} · {{ formatFileSize(attachment.sizeBytes) }} · {{ attachment.uploadedBy.fullName }}</small></div><button class="text-button" @click="download(attachment)">Descargar</button><button v-if="canDeleteAttachment(attachment)" class="text-button danger" :disabled="busy" @click="run(() => attachmentsService.remove(task.id, attachment.id))">Eliminar</button></li><li v-if="!attachments.length" class="muted">No hay archivos adjuntos.</li></ul></section><section class="detail-section comments"><header><h2>Comentarios</h2></header><form class="comment-form" @submit.prevent="comment"><textarea v-model="commentContent" maxlength="4000" placeholder="Escribe una actualización para el equipo" required /><button class="button primary" :disabled="busy">Comentar</button></form><ol class="comment-list"><li v-for="commentItem in comments" :key="commentItem.id"><header><b>{{ commentItem.author.fullName }}</b><small>{{ new Date(commentItem.createdAt).toLocaleString('es-PE') }} <em v-if="commentItem.isEdited">Editado</em></small></header><textarea v-if="editingComment?.id === commentItem.id" v-model="editingComment.content" /><p v-else>{{ commentItem.content }}</p><div v-if="canDeleteComment(commentItem)"><button v-if="commentItem.author.id === auth.user?.id" class="text-button" @click="editingComment = { ...commentItem }">Editar</button><button v-if="editingComment?.id === commentItem.id" class="text-button" @click="updateComment(commentItem)">Guardar</button><button class="text-button danger" :disabled="busy" @click="run(() => commentsService.remove(task.id, commentItem.id))">Eliminar</button></div></li><li v-if="!comments.length" class="muted">Aún no hay comentarios.</li></ol></section><section class="detail-section activity"><header><h2>Actividad</h2></header><ol><li v-for="item in activity" :key="item.id"><span class="activity-dot"></span><div><b>{{ item.actor.fullName }}</b> {{ activityText(item) }}<small>{{ new Date(item.occurredAt).toLocaleString('es-PE') }}</small></div></li><li v-if="!activity.length" class="muted">Aún no hay actividad registrada.</li></ol></section></div><BaseModal v-model="editModal" title="Editar tarea"><TaskForm :task="task" :submitting="busy" @submit="form => run(async () => { await tasksService.update(task.id, taskPayload(form, task.version)); editModal = false })" /></BaseModal></AsyncState></section></template>
